import sys


def boundary_values(limits):
    """limits: the upper limits of the income slabs, in any order. Return the test incomes for boundary value analysis: 0, and for every limit b the values b - 1, b and b + 1 (never below 0), sorted, each once."""
    values = {0}
    for b in limits:
        values.update(v for v in (b - 1, b, b + 1) if v >= 0)
    return sorted(values)


def main():
    limits = list(map(int, sys.stdin.read().split()))
    print(" ".join(map(str, boundary_values(limits))))


main()

import re
import sys


def group_failures(messages):
    """Normalise each failure message: replace every part in single or double quotes with S, then every run of digits with N. Return [(count, normalised message)] for each distinct one, most frequent first, ties by message."""
    counts = {}
    for message in messages:
        shape = re.sub(r"'[^']*'|\"[^\"]*\"", "S", message)     # quoted selectors, names, dates
        shape = re.sub(r"\d+", "N", shape)                         # timings, ids, counts
        counts[shape] = counts.get(shape, 0) + 1
    return sorted(((c, m) for m, c in counts.items()), key=lambda x: (-x[0], x[1]))


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    for count, message in group_failures(data[1:1 + n]):
        print(count, message)


main()

import sys


def hidden_dependencies(steps):
    """steps: (test, READ or WRITE, key) in run order. A test depends on another when it READs a key whose latest write came from a different test and it has not written that key itself earlier. Return the distinct (reader, writer, key) triples, sorted."""
    last_writer, wrote = {}, set()
    found = set()
    for test, op, key in steps:
        if op == "WRITE":
            last_writer[key] = test
            wrote.add((test, key))
        elif key in last_writer and last_writer[key] != test and (test, key) not in wrote:
            found.add((test, last_writer[key], key))      # it reads someone else's leftovers
    return sorted(found)


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    steps = [tuple(data[1 + i].split()) for i in range(n)]
    pairs = hidden_dependencies(steps)
    if not pairs:
        print("ISOLATED")
    for reader, writer, key in pairs:
        print(reader, "<-", writer, key)


main()

import json
import sys


def json_type(value):
    if value is None:
        return "null"
    if isinstance(value, bool):                 # check bool before number: True is an int in Python
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return {str: "string", dict: "object", list: "array"}[type(value)]


def verify(contract, response):
    """contract: (dotted path, type) with type one of string, number, boolean, object, array, null. response: parsed JSON. Follow each path through objects. Return, in contract order, 'missing PATH' or 'type PATH expected=T got=U'. true/false are boolean, never number."""
    problems = []
    for path, expected in contract:
        node, found = response, True
        for part in path.split("."):
            if isinstance(node, dict) and part in node:
                node = node[part]
            else:
                found = False
                break
        if not found:
            problems.append(f"missing {path}")
        elif json_type(node) != expected:
            problems.append(f"type {path} expected={expected} got={json_type(node)}")
    return problems


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    contract = [tuple(data[1 + i].split()) for i in range(n)]
    response = json.loads(data[1 + n])
    problems = verify(contract, response)
    print("\n".join(problems) if problems else "PASS")


main()
